/** What surrounds the scene: its name, the background and the ambient light. */
@Serializable
data class Environment(
    /** The scene's name; `""` shows the name it was created with. */
    val name: String,
    /** Viewport background, `#rrggbb`. */
    val background: String,
    /** Ambient light colour, `#rrggbb`. */
    @SerialName("ambient_color") val ambientColor: String,
    /** Ambient light strength, 0 to 10. */
    @SerialName("ambient_intensity") val ambientIntensity: Double,
    /** Set by the contract. */
    @SerialName("updated_at") val updatedAt: ULong,
)

/** A check-out: one editor holding an asset until they check it in or it lapses. */
@Serializable
data class Lock(
    @SerialName("asset_id") val assetId: String,
    /** Set by the contract. */
    val holder: String,
    val since: ULong,
    /** After this (the holder's clock, unix milliseconds) the lock no longer holds. */
    @SerialName("expires_at") val expiresAt: ULong,
    @SerialName("updated_at") val updatedAt: ULong,
)

/** A live check-out. */
@Serializable
data class LockView(
    @SerialName("asset_id") val assetId: String,
    val holder: String,
    val since: ULong,
    @SerialName("expires_at") val expiresAt: ULong,
